// with the let example https://p5js.org/learn/getting-started-in-webgl-framebuffers.html (Fedback!)
// in a shader
// the buffer to the shader as a texture (let Feedback!)
// another canvas with creategraphics
// some squares on that
// from https://farbvelo.elastiq.ch/
// the two textures in the shader.
// and rotated a cube a bit with sin for that framebuffer goodness

// timings are a whole mess that I've not fixed, forgot to pass time to my shader at one point so thought it wasnt working so started counting frames and passing that.
// for some reason let use frameCount for bit. let some things are timed with millis() some my frameNum, some P5's frameCount. 
// moves way too fast if the frameCount gets high, let think let can manually set the frameCount in P5, I'm not gonna do that because let cant be bothered to work out what speed i want.

// that seems overly lazy to you.... 
// accept that feedback!, but im not changing it now.  

let prev, next;

let palette= [
  "#def36", 
  "#d986c3", 
  "#ae9d51", 
  "#977567", 
  "#bf34bf", 
  "#3b6cb0", 
  "#430ebc", 
  "#360a5d", 
  "#191033", 
  "#0e1016"
]


let frameNum = 1
let size = 100

let myShader;
let pg;

function preload() {

  myShader = loadShader('https://openprocessing.org/sketch/2244481/files/shader.vert', 'shader.frag');
}
function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
  prev = createFramebuffer({ format: FLOAT });
  next = createFramebuffer({ format: FLOAT });
	pg = createGraphics(windowHeight, windowHeight);
  imageMode(CENTER);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);

}


function draw() {


	for(let i =0; i<windowWidth; i+=(Math.max(0.001, Math.abs(size)) || 1)){

		for(let j =0; j<windowHeight; j+=(Math.max(0.001, Math.abs(size)) || 1)){

			let distance = dist(i, j, windowWidth * 0.5, windowHeight * 0.5)

			let normalizedDistance = map(distance, 0, windowWidth, 0, 1); 

			pg.strokeWeight(Math.max(0.1, Math.abs((1-normalizedDistance))) * 5)
			pg.stroke(255)					
			pg.fill(palette[(((i+j) /size) % palette.length)])
			pg.rect(i ,j ,size  , size  ) 




			resetShader()





		}
	}



  // prev and next
  [prev, next] = [next, prev];
	frameNum ++
  // next and draw a new next frame
  next.begin();
  clear();
	background(0)

  // rotate and scale the last frame
  push();
  rotate(( Math.sin(frameNum * .01)));
  scale( .9 * cos(frameCount*0.01));
  image(prev, 0, 0);
  pop();


	stroke(255)
	strokeWeight(3 *Math.cos(frameCount * .01))
	myShader.setUniform("u_time", millis() / 1000.0);
	myShader.setUniform("uTexture", prev);
	myShader.setUniform('uTexture2', pg);
	myShader.setUniform('frameNum', frameNum);
  shader(myShader)
	rotateX(frameCount * 0.02);
  rotateY(frameCount * 0.02);
	box(1750 , 1750, 1750 );


  next.end();

  background(255);
  image(next, 0, 0);
}
